const quantidade = $json.quantidade;

// 🔒 Regras fixas do time
const SENHA_PADRAO = "Qa@12345";
const EMAIL_BASE = "nome.sobrenome";
const DOMINIO_EMAIL = "empresa.dev";

// Listas ampliadas de nomes
const nomes = [
  "Ana", "João", "Maria", "Pedro", "Lucas", "Carla",
  "Bruno", "Juliana", "Rafael", "Camila", "Thiago",
  "Fernanda", "Gabriel", "Mariana", "Diego", "Paula"
];

const sobrenomes = [
  "Silva", "Santos", "Oliveira", "Costa", "Pereira",
  "Rodrigues", "Almeida", "Lima", "Gomes", "Ribeiro",
  "Martins", "Araujo"
];

// 🧾 Gera CPF válido e formatado
function gerarCPFFormatado() {
  const rand = () => Math.floor(Math.random() * 9);
  const nums = Array.from({ length: 9 }, rand);

  const calcDigito = (base) => {
    let soma = 0;
    for (let i = 0; i < base.length; i++) {
      soma += base[i] * (base.length + 1 - i);
    }
    const resto = soma % 11;
    return resto < 2 ? 0 : 11 - resto;
  };

  const digito1 = calcDigito(nums);
  const digito2 = calcDigito([...nums, digito1]);

  const cpfNumerico = [...nums, digito1, digito2].join("");

  return cpfNumerico.replace(
    /(\d{3})(\d{3})(\d{3})(\d{2})/,
    "$1.$2.$3-$4"
  );
}

const resultado = [];

for (let i = 1; i <= quantidade; i++) {
  const nome = nomes[Math.floor(Math.random() * nomes.length)];
  const sobrenome = sobrenomes[Math.floor(Math.random() * sobrenomes.length)];
  const nomeCompleto = `${nome} ${sobrenome}`;

  const numero = String(i).padStart(2, "0");
  const email = `${EMAIL_BASE}+${numero}@${DOMINIO_EMAIL}`;
  const cpf = gerarCPFFormatado();

  resultado.push({
    Nome: nomeCompleto,
    Email: email,
    CPF: cpf,
    Senha: SENHA_PADRAO
  });
}

return resultado.map(item => ({ json: item }));
